import React, { useEffect } from "react";

import invalidTokenForwardToLogin from "../../../toggles/invalid-token--forward-to-login";
import { useAuth } from "../../../config/opencms--useAuth";

export const OpenCmsLogout: React.FC = () => {
  const { logout } = useAuth();

  useEffect(() => {
    if (typeof window === "undefined") return;

    async function doLogout() {
      await logout();

      if (invalidTokenForwardToLogin) {
        window.location.replace("/login");
      }
    }

    doLogout();
  }, [logout]);

  return (
    <div
      style={{
        minHeight: "100vh",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "#f0f2f5",
      }}
    >
      <p style={{ fontSize: 18, color: "#555" }}>Logging out…</p>
    </div>
  );
};

export default OpenCmsLogout;